import { PropsWithChildren } from 'react';

import {
  HistogramThresholdData,
  HistogramThresholdPosition,
} from '../../core/types/thresholds.js';

export interface HistogramThresholdProps {
  /** The threshold data to be graphed by the component */
  data: HistogramThresholdData;
  /** The unique color picked for this histogram representation in HEX, RGB, Color Token or HSL.*/
  color: string;
  /** The position of the threshold relative to the histogram chart. */
  position?: HistogramThresholdPosition;
  /** Whereas to show the ranges filled or only the strokes */
  strokeOnly?: boolean;
  /**
   * Label to be shown in the threshold tooltip.
   * @defaultValue "Threshold"
   */
  label?: string;
}

export const Threshold = (props: PropsWithChildren<HistogramThresholdProps>) =>
  null;
